import { type RefObject, useEffect, useEffectEvent } from 'react';
import { useEditorEngineOptional } from './editor-engine-context';

interface SceneElementEventListenerOptions extends AddEventListenerOptions {
  allowWhileSceneInteractionBlocked?: boolean;
  enabled?: boolean | (() => boolean);
}

type SceneElementEventTarget = EventTarget | RefObject<EventTarget | null> | null;

/**
 * Registers a direct DOM/window/document listener on the scene-element channel.
 *
 * R3F handlers are filtered centrally after raycasting. Features that must use
 * addEventListener instead use this adapter, which applies the same engine gate
 * without stopping propagation to camera controls or unrelated listeners.
 */
export function useSceneElementEventListener<TEvent extends Event>(
  target: SceneElementEventTarget,
  type: string,
  listener: (event: TEvent) => void,
  options?: SceneElementEventListenerOptions
): void {
  // Production editor mounts always provide the engine. The optional read keeps
  // isolated hook/component tests and non-editor renderers backward-compatible;
  // no engine means the historical ungated behavior.
  const engine = useEditorEngineOptional();
  const dispatch = useEffectEvent((event: Event) => listener(event as TEvent));
  const allowWhileSceneInteractionBlocked = options?.allowWhileSceneInteractionBlocked ?? false;
  const enabled = options?.enabled ?? true;
  const capture = options?.capture;
  const once = options?.once;
  const passive = options?.passive;
  const signal = options?.signal;
  const hasCapture = options !== undefined && 'capture' in options;
  const hasOnce = options !== undefined && 'once' in options;
  const hasPassive = options !== undefined && 'passive' in options;
  const hasSignal = options !== undefined && 'signal' in options;

  useEffect(() => {
    const resolvedTarget = target && 'current' in target ? target.current : target;
    if (!resolvedTarget || enabled === false) return;

    const guardedListener: EventListener = (event) => {
      if (typeof enabled === 'function' && !enabled()) return;
      if (!allowWhileSceneInteractionBlocked && engine?.sceneInteraction.areElementEventsBlocked) return;
      dispatch(event);
    };

    const hasListenerOptions = hasCapture || hasOnce || hasPassive || hasSignal;
    if (!hasListenerOptions) {
      resolvedTarget.addEventListener(type, guardedListener);
      return () => resolvedTarget.removeEventListener(type, guardedListener);
    }

    const listenerOptions: AddEventListenerOptions = {};
    if (hasCapture) listenerOptions.capture = capture;
    if (hasOnce) listenerOptions.once = once;
    if (hasPassive) listenerOptions.passive = passive;
    if (hasSignal) listenerOptions.signal = signal;
    resolvedTarget.addEventListener(type, guardedListener, listenerOptions);
    return () => resolvedTarget.removeEventListener(type, guardedListener, listenerOptions);
  }, [
    allowWhileSceneInteractionBlocked,
    capture,
    enabled,
    engine,
    hasCapture,
    hasOnce,
    hasPassive,
    hasSignal,
    once,
    passive,
    signal,
    target,
    type,
  ]);
}
