      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function));
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function));
  });

  it('keeps explicit false capture options explicit for registration and cleanup', () => {
    const target = {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener, { capture: false }));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: false });
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: false });
  });

  it('keeps explicit true capture options explicit for registration and cleanup', () => {
    const target = {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener, { capture: true }));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: true });
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: true });
  });

