    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(2);

    act(() => engine.sceneInteraction.setNavigationIntent(navigationOwner, false));
    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(3);
