import { EditorEngineProvider } from '../editor-engine-context';
import { useSceneElementEventListener } from '../use-scene-element-event-listener';

describe('useSceneElementEventListener', () => {
  it('keeps omitted listener options omitted for registration and cleanup', () => {
    const target = {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function));
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function));
  });

  it('keeps explicit false capture options explicit for registration and cleanup', () => {
    const target = {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener, { capture: false }));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: false });
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: false });
  });

  it('keeps explicit true capture options explicit for registration and cleanup', () => {
    const target = {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener, { capture: true }));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: true });
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), { capture: true });
  });

  it('passes passive, once, and signal options through unchanged', () => {
    const target = {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    } as unknown as EventTarget;
    const listener = vi.fn();
    const signal = new AbortController().signal;
    const options = { passive: true, once: true, signal };

    const { unmount } = renderHook(() => useSceneElementEventListener(target, 'keydown', listener, options));

    expect(target.addEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), options);
    unmount();
    expect(target.removeEventListener).toHaveBeenCalledWith('keydown', expect.any(Function), options);
  });

  it('resolves a ref target when the effect attaches and removes the listener', () => {
    const target = new EventTarget();
    const targetRef = { current: target };
    const listener = vi.fn();

    const { unmount } = renderHook(() => useSceneElementEventListener(targetRef, 'keydown', listener));

    target.dispatchEvent(new Event('keydown'));
    expect(listener).toHaveBeenCalledTimes(1);

    unmount();
    target.dispatchEvent(new Event('keydown'));
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it('accepts the four-argument replacement shape and applies its options', () => {
    const target = new EventTarget();
    const listener = vi.fn();

    const { rerender } = renderHook(
      ({ enabled }) => useSceneElementEventListener(target, 'keydown', listener, { enabled, capture: true }),
      { initialProps: { enabled: false } }
    );

    target.dispatchEvent(new Event('keydown'));
    expect(listener).not.toHaveBeenCalled();

    rerender({ enabled: true });
    target.dispatchEvent(new Event('keydown'));
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it('uses the central navigation/drag arbitration for direct event listeners', async () => {
    const engine = createEditorEngine();
    const target = new EventTarget();
    const listener = vi.fn();
    const navigationOwner = Symbol('camera-navigation');
    const wrapper = ({ children }: PropsWithChildren) => (
      <EditorEngineProvider engine={engine}>{children}</EditorEngineProvider>
    );

    renderHook(() => useSceneElementEventListener(target, 'pointerdown', listener), { wrapper });

    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(1);

    act(() => engine.sceneInteraction.setNavigationIntent(navigationOwner, true));
    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(1);

    const dragLease = engine.tryClaimDragSession({ pointerId: 1, abort: () => {} });
    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(2);

    await act(async () => {
      dragLease?.release();
      await Promise.resolve();
    });
    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(2);

    act(() => engine.sceneInteraction.setNavigationIntent(navigationOwner, false));
    target.dispatchEvent(new Event('pointerdown'));
    expect(listener).toHaveBeenCalledTimes(3);
  });

  it('keeps a gate-owning lifecycle listener live while its navigation block is active', () => {
    const engine = createEditorEngine();
    const target = new EventTarget();
    const blockedListener = vi.fn();
    const lifecycleListener = vi.fn();
    const navigationOwner = Symbol('camera-navigation');
    const wrapper = ({ children }: PropsWithChildren) => (
      <EditorEngineProvider engine={engine}>{children}</EditorEngineProvider>
    );

    renderHook(() => useSceneElementEventListener(target, 'keyup', blockedListener), { wrapper });
    renderHook(
      () =>
        useSceneElementEventListener(target, 'keyup', lifecycleListener, {
          allowWhileSceneInteractionBlocked: true,
        }),
      { wrapper }
    );

    act(() => engine.sceneInteraction.setNavigationIntent(navigationOwner, true));
    target.dispatchEvent(new Event('keyup'));

    expect(blockedListener).not.toHaveBeenCalled();
    expect(lifecycleListener).toHaveBeenCalledTimes(1);
  });
});
