const FEATURES_ROOT = join(REPO_ROOT, 'packages/frontend/src/features/3d-viz-v2');
const RULE = CANONICAL_RULES.find((rule): rule is OnlyInsideRule => rule.kind === 'only-inside');

if (!RULE) throw new Error('keyboard-listener only-inside rule is missing');

const file = (path: string, source: string): SourceFile => ({ path, source });

describe('raw keyboard listener detector', () => {
  it('catches named globals and arbitrary element receivers with file:line diagnostics', () => {
    const source = file(
      'packages/frontend/src/features/3d-viz-v2/components/keys.tsx',
      [
        "window.addEventListener('keydown', onDown);",
        'document.addEventListener("keyup", onUp);',
        "canvas.addEventListener('keypress', onPress, true);",
        "container.addEventListener('keydown', onContainerDown);",
        "containerRef.current.addEventListener('keyup', onRefUp);",
        "root.addEventListener('keypress', onRootPress);",
      ].join('\n')
    );

    const violations = findRestrictedListeners(RULE, [source]);

    expect(violations.map(({ receiver, channel, line }) => [receiver, channel, line])).toEqual([
      ['window', 'keydown', 1],
      ['document', 'keyup', 2],
      ['canvas', 'keypress', 3],
      ['container', 'keydown', 4],
      ['containerRef.current', 'keyup', 5],
      ['root', 'keypress', 6],
    ]);
    expect(formatRestrictedListenerViolation(violations[0])).toContain(`${source.path}:1 [keyboard-listener]`);
    expect(formatRestrictedListenerViolation(violations[0])).toContain(RULE.replacement);
  });

  it('catches non-literal names, key properties, and EventTarget prototype calls without flagging cleanup', () => {
    const source = file(
      'packages/frontend/src/features/3d-viz-v2/components/evasive-keys.tsx',
      [
        "const KEY_DOWN = 'keydown';",
        "window.addEventListener('key' + 'down', onKeyDown);",
        'document.addEventListener(KEY_DOWN, onKeyDown);',
        'window.onkeydown = onKeyDown;',
        'window.onkeydown = null;',
        'document.onkeyup = onKeyUp;',
        'document.onkeyup = undefined;',
        "EventTarget.prototype.addEventListener.call(window, 'keypress', onKeyPress);",
      ].join('\n')
    );

    const violations = findRestrictedListeners(RULE, [source]);

    expect(
      violations.map(({ receiver, channel, channelIsLiteral, line }) => [receiver, channel, channelIsLiteral, line])
    ).toEqual([
      ['window', "'key' + 'down'", false, 2],
      ['document', 'KEY_DOWN', false, 3],
      ['window', 'keydown', true, 4],
      ['document', 'keyup', true, 6],
      ['window', 'keypress', true, 8],
    ]);
    expect(formatRestrictedListenerViolation(violations[0])).toContain(
      "uses non-literal event name 'key' + 'down' outside the engine boundary"
    );
    expect(formatRestrictedListenerViolation(violations[0])).toContain(
      'the rule cannot prove it is not a keyboard channel'
    );
  });

  it('ignores comments, non-scene receivers, adapter aliases, and allowed paths without losing code after a URL', () => {
    const files = [
      file(
        'packages/frontend/src/features/3d-viz-v2/components/comment.tsx',
        "// window.addEventListener('keydown', no);"
      ),
      file(
        'packages/frontend/src/features/3d-viz-v2/components/block.tsx',
        "/* document.addEventListener('keyup', no); */"
      ),
      file('packages/frontend/src/features/3d-viz-v2/components/input.tsx', "input.addEventListener('keydown', no);"),
      file(
        'packages/frontend/src/features/3d-viz-v2/components/adapter.tsx',
        "import { useSceneElementEventListener as useKeys } from '../api/engine/use-scene-element-event-listener';\nuseKeys(window, 'keydown', onDown);"
      ),
      file(
        'packages/frontend/src/features/3d-viz-v2/api/engine/internal.ts',
        "window.addEventListener('keydown', allowed);"
      ),
      file(
        'packages/frontend/src/features/3d-viz-v2/api/active-scene-drag.ts',
        "window.addEventListener('keydown', allowed);"
      ),
    ];

    expect(findRestrictedListeners(RULE, files)).toEqual([]);
    expect(
      findRestrictedListeners(RULE, [
        file(
          'packages/frontend/src/features/3d-viz-v2/components/url.tsx',
          "log('https://example.test'); window.addEventListener('keydown', onDown);"
        ),
      ])
    ).toHaveLength(1);
  });

  it('keeps every labeled fire and no-fire corpus verdict', () => {
    const corpus = JSON.parse(
      readFileSync(
        join(REPO_ROOT, 'packages/frontend/scripts/canonical/__fixtures__/keyboard-listener-corpus.json'),
        'utf8'
      )
    ) as { cases: { label: string; path: string; source: string; expected: 'fire' | 'no-fire' }[] };

    expect(corpus.cases.filter(({ expected }) => expected === 'fire')).toHaveLength(14);
    expect(corpus.cases.filter(({ expected }) => expected === 'no-fire').length).toBeGreaterThanOrEqual(5);
    for (const entry of corpus.cases) {
      const verdict = findRestrictedListeners(RULE, [file(entry.path, entry.source)]).length > 0 ? 'fire' : 'no-fire';
      expect([entry.label, verdict]).toEqual([entry.label, entry.expected]);
    }
  });
});

